import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate, useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaLista = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();
  const { id } = useParams(); // Obtém o ID do professor da URL

  const fetchCursos = async () => {
    try {
      setLoading(true);
      setError(null);

      const resposta = await private_api.get(`/professores/${id}/listacursos`);
      if (resposta.status === 200) {
        setCursos(resposta.data);
      } else {
        console.error("Erro ao buscar cursos");
        setError("Erro ao carregar os cursos. Tente novamente mais tarde.");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
      setError(
        "Falha ao conectar ao servidor. Verifique sua conexão e tente novamente."
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (id) {
      fetchCursos();
    } else {
      setLoading(false);
      setError("ID do professor não encontrado.");
    }
  }, [id]);

  if (loading) {
    return (
      <div
        className="d-flex justify-content-center align-items-center"
        style={{ minHeight: "100vh" }}
      >
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mt-5">
        <div className="alert alert-danger text-center">
          {error}
          <button
            className="btn btn-sm btn-outline-danger ms-3"
            onClick={fetchCursos}
          >
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link active" href="#">
          Cursos
        </a>
        <a
          className="nav-link"
          href="#"
          onClick={() => navigate(`/professoraulas/${id}`)}
        >
          Aulas
        </a>
        <a
          className="nav-link"
          href="#"
          onClick={() => navigate(`/professoravaliacoes/${id}`)}
        >
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Lista de Cursos à lecionar</h2>

      <div className="w-75 mb-3">
        <button
          className="btn btn-primary"
          onClick={fetchCursos}
          disabled={loading}
        >
          {loading ? "Atualizando..." : "Atualizar Lista"}
        </button>
      </div>

      <table className="table table-bordered bg-white w-75">
        <thead className="table-light">
          <tr>
            <th>Curso</th>
            <th>Nível</th>
            <th>Data de Início</th>
            <th>Data de Fim</th>
            <th>Período</th>
          </tr>
        </thead>
        <tbody>
          {cursos.length > 0 ? (
            cursos.map((curso) => (
              <tr key={curso.id}>
                <td>{curso.nome}</td>
                <td>{curso.nivel}</td>
                <td>
                  {new Date(curso.dataInicio).toLocaleDateString("pt-PT")}
                </td>
                <td>{new Date(curso.dataFim).toLocaleDateString("pt-PT")}</td>
                <td>{curso.periodo}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5" className="text-center">
                Nenhum curso encontrado
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default LecionaLista;
